export function validateForm(data: { name: string; email: string; password: string; confirmPassword: string }): { isValid: boolean; errors: string[] } {
    const errors: string[] = [];
    if (!data.name) errors.push('Name is required');
    if (!data.email) errors.push('Email is required');
    if (!data.password) errors.push('Password is required');
    if (data.password !== data.confirmPassword) errors.push('Passwords do not match');
    return { isValid: errors.length === 0, errors };
}

export function processInput(input: string): { isValid: boolean; errors: string[]; transformed: { name: string; email: string; password: string; confirmPassword: string } } {
    try {
        const parsedData = JSON.parse(input);
        const validationResult = validateForm(parsedData);
        if (validationResult.isValid) {
            return validationResult;
        }
        return { isValid: false, errors: validationResult.errors, transformed: parsedData };
    } catch (err) {
        return { isValid: false, errors: [err.message], transformed: {} };
    }
}

export function handleFileInput(filePath: string): { isValid: boolean; errors: string[]; transformed: { name: string; email: string; password: string; confirmPassword: string } } {
    try {
        const data = require(filePath);
        const validationResult = processInput(JSON.stringify(data));
        if (validationResult.isValid) {
            return validationResult;
        }
        return { isValid: false, errors: validationResult.errors, transformed: {} };
    } catch (err) {
        return { isValid: false, errors: [err.message], transformed: {} };
    }
}

export function saveToFile(filePath: string, data: { name: string; email: string; password: string; confirmPassword: string }) {
    try {
        const validationResult = validateForm(data);
        if (validationResult.isValid) {
            const transformedData = { name: data.name, email: data.email, password: data.password, confirmPassword: data.confirmPassword };
            const json = JSON.stringify(transformedData, null, 2);
            require('fs').writeFileSync(filePath, json);
        }
    } catch (err) {
        console.error(err);
    }
}

