export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="header">
      <h1>Form Validator</h1>
      <div class="controls">
        <button id="validateBtn" class="btn primary">Validate</button>
        <button id="resetBtn" class="btn">Reset</button>
      </div>
    </div>
    <div class="form">
      <label>Name <input id="name" type="text" value="John Doe"></label>
      <label>Email <input id="email" type="email" value="john@example.com"></label>
      <label>Password <input id="password" type="password" value="password123"></label>
      <label>Confirm Password <input id="confirmPassword" type="password" value="password123"></label>
      <button id="addFieldBtn" class="btn">Add Field</button>
    </div>
    <div class="results" id="results"></div>
  `;

  const validateBtn = document.getElementById('validateBtn');
  const resetBtn = document.getElementById('resetBtn');
  const nameInput = document.getElementById('name');
  const emailInput = document.getElementById('email');
  const passwordInput = document.getElementById('password');
  const confirmPasswordInput = document.getElementById('confirmPassword');
  const addFieldBtn = document.getElementById('addFieldBtn');
  const resultsDiv = document.getElementById('results');

  const fields = [
    { label: 'Name', name: 'name', value: '', type: 'text' },
    { label: 'Email', name: 'email', value: '', type: 'email' },
    { label: 'Password', name: 'password', value: '', type: 'password' },
    { label: 'Confirm Password', name: 'confirmPassword', value: '', type: 'password' },
  ];

  function validate() {
    let isValid = true;
    let errors = [];
    for (const field of fields) {
      if (field.type === 'text' && !field.value) { isValid = false; errors.push(`Field ${field.label} is required`); continue; }
      if (field.type === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(field.value)) { isValid = false; errors.push(`Field ${field.label} is invalid`); continue; }
      if (field.type === 'password' && field.value !== confirmPasswordInput.value) { isValid = false; errors.push(`Field ${field.label} does not match Confirm Password`); continue; }
    }
    resultsDiv.innerHTML = errors.length > 0 ? errors.map((e, i) => `<div class="error">${i + 1}. ${e}</div>`).join('') : '<div class="success">All fields are valid</div>';
  }

  validateBtn.addEventListener('click', validate);
  resetBtn.addEventListener('click', () => { nameInput.value = ''; emailInput.value = ''; passwordInput.value = ''; });
  addFieldBtn.addEventListener('click', () => {
    const field = { label: `Field ${fields.length + 1}`, name: `field${fields.length + 1}`, value: '', type: 'text' };
    fields.push(field);
    validate();
  });
}

