export function storeState(state: any): void {
  try {
    const data = JSON.stringify(state);
    const fs = require('fs');
    fs.writeFileSync('data.json', data);
  } catch (err) {
    throw new Error(`Error storing states in data.json: ${err}`);
  }
}

export function loadState(): any {
  try {
    const fs = require('fs');
    const data = fs.readFileSync('data.json', 'utf8');
    return JSON.parse(data);
  } catch (err) {
    // Log or handle the error
    console.error(`Error loading state from data.json: ${err}`);
    return {};
  }
}

export function setState(key: string, value: any): void {
  const currentState = loadState();
  currentState[key] = value;
  storeState(currentState);
}

export function getState(key: string): any {
  const state = loadState();
  return state[key];
}
